```go
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"strings"
)

type Record []string

func parseCSV(input string, delimiter rune, quoteChar rune) ([]Record, error) {
	var records []Record
	scanner := bufio.NewScanner(strings.NewReader(input))
	for scanner.Scan() {
		line := scanner.Text()
		record, err := parseLine(line, delimiter, quoteChar)
		if err != nil {
			return nil, err
		}
		records = append(records, record)
	}
	return records, nil
}

func parseLine(line string, delimiter rune, quoteChar rune) (Record, error) {
	var fields []string
	var field bytes.Buffer
	inQuote := false

	for _, c := range line {
		if c == quoteChar {
			inQuote = !inQuote
		} else if c == delimiter && !inQuote {
			fields = append(fields, field.String())
			field.Reset()
		} else {
			field.WriteRune(c)
		}
	}

	fields = append(fields, field.String())

	return Record(fields), nil
}

func main() {
	csv := `name,age
John Doe,"25,000"
Jane "The Queen" Smith,30`
	records, err := parseCSV(csv, ',', '"')
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	for _, record := range records {
		fmt.Println(record)
	}
}
